13	func (d *DB) CreateUser(ctx context.Context, create *store.User) (*store.User, error) {
14		fields := []string{"`username`", "`role`", "`email`", "`nickname`", "`password_hash`", "`avatar_url`"}
15		placeholder := []string{"?", "?", "?", "?", "?", "?"}
16		args := []any{create.Username, create.Role, create.Email, create.Nickname, create.PasswordHash, create.AvatarURL}
17	
18		stmt := "INSERT INTO user (" + strings.Join(fields, ", ") + ") VALUES (" + strings.Join(placeholder, ", ") + ")"
19		result, err := d.db.ExecContext(ctx, stmt, args...)
20		if err != nil {
21			return nil, err
22		}
23	
24		id, err := result.LastInsertId()
25		if err != nil {
26			return nil, err
27		}
28	
29		id32 := int32(id)
30		list, err := d.ListUsers(ctx, &store.FindUser{ID: &id32})
31		if err != nil {
32			return nil, err
33		}
34		if len(list) != 1 {
35			return nil, errors.Errorf("unexpected user count: %d", len(list))
36		}
37	
38		return list[0], nil
39	}
