146		}
147		query := "SELECT `id`, `username`, `role`, `email`, `nickname`, `password_hash`, `avatar_url`, `description`, UNIX_TIMESTAMP(`created_ts`), UNIX_TIMESTAMP(`updated_ts`), `row_status` FROM `user` WHERE " + strings.Join(where, " AND ") + " ORDER BY " + strings.Join(orderBy, ", ")
148		if v := find.Limit; v != nil {
149			query += fmt.Sprintf(" LIMIT %d", *v)
150			if v := find.Offset; v != nil {
151				query += fmt.Sprintf(" OFFSET %d", *v)
